IS=[("İmanın esasları",[
("İslam'da imanın altı esası vardır.","Im Islam gibt es sechs Glaubensgrundsätze.","En islam, il y a six piliers de la foi.","En el islam hay seis pilares de la fe."),
("Birincisi, Allah'a imandır.","Der erste ist der Glaube an Allah.","Le premier est la foi en Allah.","El primero es la fe en Allah."),
("Allah birdir; ortağı ve benzeri yoktur.","Allah ist einer; Er hat keinen Partner und nichts ist Ihm gleich.","Allah est unique ; Il n'a ni associé ni semblable.","Allah es uno; no tiene socio ni semejante."),
("İkincisi, meleklere imandır.","Der zweite ist der Glaube an die Engel.","Le deuxième est la foi aux anges.","El segundo es la fe en los ángeles."),
("Üçüncüsü, Allah'ın indirdiği kitaplara imandır.","Der dritte ist der Glaube an die Bücher, die Allah herabgesandt hat.","Le troisième est la foi aux livres révélés par Allah.","El tercero es la fe en los libros que Allah reveló."),
("Tevrat, Zebur, İncil ve Kur'an bu kitaplardandır.","Die Tora, die Psalmen, das Evangelium und der Koran gehören zu diesen Büchern.","La Torah, les Psaumes, l'Évangile et le Coran font partie de ces livres.","La Torá, los Salmos, el Evangelio y el Corán están entre esos libros."),
("Dördüncüsü, peygamberlere imandır.","Der vierte ist der Glaube an die Propheten.","Le quatrième est la foi aux prophètes.","El cuarto es la fe en los profetas."),
("İlk peygamber Hz. Âdem, son peygamber Hz. Muhammed'dir.","Der erste Prophet ist Adam, der letzte ist Muhammad.","Le premier prophète est Adam, le dernier est Muhammad.","El primer profeta es Adán y el último es Muhammad."),
("Beşincisi, âhiret gününe imandır.","Der fünfte ist der Glaube an den Jüngsten Tag.","Le cinquième est la foi au Jour dernier.","El quinto es la fe en el Día del Juicio."),
("Altıncısı, kadere, hayrın ve şerrin Allah'tan olduğuna imandır.","Der sechste ist der Glaube an die Vorherbestimmung, an das Gute und das Schlechte.","Le sixième est la foi au destin, au bien comme au mal.","El sexto es la fe en el destino, en lo bueno y en lo malo.")]),
("İslam'ın beş şartı",[
("İslam beş temel üzerine kurulmuştur.","Der Islam ist auf fünf Säulen gebaut.","L'islam est bâti sur cinq piliers.","El islam se basa en cinco pilares."),
("Birincisi kelime-i şehadettir.","Die erste Säule ist das Glaubensbekenntnis.","Le premier pilier est l'attestation de foi.","El primero es la declaración de fe."),
("Müslüman, Allah'tan başka ilah olmadığına ve Muhammed'in O'nun elçisi olduğuna şahitlik eder.","Der Muslim bezeugt, dass es keinen Gott außer Allah gibt und dass Muhammad Sein Gesandter ist.","Le musulman atteste qu'il n'y a de dieu qu'Allah et que Muhammad est Son messager.","El musulmán atestigua que no hay más dios que Allah y que Muhammad es Su mensajero."),
("İkincisi namaz kılmaktır.","Die zweite ist das Gebet.","Le deuxième est la prière.","El segundo es la oración."),
("Üçüncüsü zekât vermektir.","Die dritte ist die Zakat, die Pflichtabgabe.","Le troisième est l'aumône obligatoire, la zakat.","El tercero es el azaque, la limosna obligatoria."),
("Dördüncüsü Ramazan orucunu tutmaktır.","Die vierte ist das Fasten im Ramadan.","Le quatrième est le jeûne du Ramadan.","El cuarto es el ayuno de Ramadán."),
("Beşincisi, gücü yetenin Kâbe'yi haccetmesidir.","Die fünfte ist die Pilgerfahrt zur Kaaba für den, der dazu in der Lage ist.","Le cinquième est le pèlerinage à la Kaaba pour celui qui en a les moyens.","El quinto es la peregrinación a la Kaaba para quien pueda hacerla."),
("Bu şartlar bir binanın sütunları gibidir.","Diese Säulen sind wie die Pfeiler eines Gebäudes.","Ces piliers sont comme les colonnes d'un bâtiment.","Estos pilares son como las columnas de un edificio."),
("Sütunlar sağlam olursa bina da sağlam olur.","Wenn die Pfeiler stark sind, ist auch das Gebäude stark.","Si les colonnes sont solides, le bâtiment est solide aussi.","Si las columnas son firmes, el edificio también lo es."),
("Bu hadis Buhârî ve Müslim'de rivayet edilmiştir.","Dieser Hadith wird bei al-Buchari und Muslim überliefert.","Ce hadith est rapporté par al-Boukhari et Muslim.","Este hadiz lo transmiten al-Bujari y Muslim.")]),
("Abdest",[
("Namazdan önce abdest almak gerekir.","Vor dem Gebet muss man die Gebetswaschung vollziehen.","Avant la prière, il faut faire les ablutions.","Antes de la oración hay que hacer la ablución."),
("Abdeste niyetle ve besmeleyle başlanır.","Man beginnt die Waschung mit der Absicht und mit „Bismillah“.","On commence les ablutions avec l'intention et en disant « Bismillah ».","La ablución empieza con la intención y diciendo «Bismillah»."),
("Önce eller bileklere kadar yıkanır.","Zuerst wäscht man die Hände bis zu den Handgelenken.","D'abord, on se lave les mains jusqu'aux poignets.","Primero se lavan las manos hasta las muñecas."),
("Sonra ağza ve buruna su verilir.","Dann spült man den Mund und die Nase.","Ensuite, on se rince la bouche et le nez.","Después se enjuagan la boca y la nariz."),
("Yüz alından çeneye, kulaktan kulağa kadar yıkanır.","Das Gesicht wird von der Stirn bis zum Kinn und von Ohr zu Ohr gewaschen.","On lave le visage, du front au menton et d'une oreille à l'autre.","Se lava la cara, de la frente a la barbilla y de oreja a oreja."),
("Kollar dirseklerle beraber yıkanır.","Die Arme werden einschließlich der Ellbogen gewaschen.","On lave les bras, coudes compris.","Se lavan los brazos, incluidos los codos."),
("Islak elle başa mesh edilir.","Mit nassen Händen streicht man über den Kopf.","On passe les mains mouillées sur la tête.","Se pasan las manos mojadas por la cabeza."),
("Kulaklar ve boyun da mesh edilir.","Auch über die Ohren und den Nacken wird gestrichen.","On essuie aussi les oreilles et la nuque.","También se pasan por las orejas y la nuca."),
("Son olarak ayaklar topuklarla beraber yıkanır.","Zum Schluss werden die Füße einschließlich der Knöchel gewaschen.","Enfin, on lave les pieds, chevilles comprises.","Por último, se lavan los pies, incluidos los tobillos."),
("Abdest hem bedeni hem de kalbi namaza hazırlar.","Die Waschung bereitet Körper und Herz auf das Gebet vor.","Les ablutions préparent le corps et le cœur à la prière.","La ablución prepara el cuerpo y el corazón para la oración.")]),
("Namaz",[
("Müslümanlar günde beş vakit namaz kılar.","Muslime beten fünfmal am Tag.","Les musulmans prient cinq fois par jour.","Los musulmanes rezan cinco veces al día."),
("Bu vakitler sabah, öğle, ikindi, akşam ve yatsıdır.","Diese Zeiten sind Morgen, Mittag, Nachmittag, Abend und Nacht.","Ces moments sont l'aube, midi, l'après-midi, le coucher du soleil et la nuit.","Estos momentos son el alba, el mediodía, la tarde, el ocaso y la noche."),
("Namaz Kâbe'ye yönelerek kılınır.","Man betet in Richtung der Kaaba.","On prie en direction de la Kaaba.","Se reza orientado hacia la Kaaba."),
("Namaza \"Allahu ekber\" diyerek başlanır.","Man beginnt das Gebet mit „Allahu akbar“.","On commence la prière en disant « Allahou akbar ».","La oración empieza diciendo «Allahu akbar»."),
("Ayakta Fâtiha sûresi okunur.","Im Stehen wird die Sure al-Fatiha rezitiert.","Debout, on récite la sourate al-Fatiha.","De pie se recita la sura al-Fatiha."),
("Sonra rükûya eğilinir ve secdeye varılır.","Dann verbeugt man sich und wirft sich nieder.","Ensuite, on s'incline puis on se prosterne.","Luego se inclina uno y se postra."),
("Secde, kulun Rabbine en yakın olduğu andır.","In der Niederwerfung ist der Mensch seinem Herrn am nächsten.","Dans la prosternation, le serviteur est au plus près de son Seigneur.","En la postración, el siervo está más cerca de su Señor."),
("Namaz \"Esselâmu aleyküm ve rahmetullah\" diyerek bitirilir.","Das Gebet endet mit „As-salamu alaikum wa rahmatullah“.","La prière se termine par « As-salamou alaykoum wa rahmatoullah ».","La oración termina diciendo «As-salamu alaikum wa rahmatullah»."),
("Kur'an, namazın kötülüklerden alıkoyduğunu bildirir.","Der Koran sagt, dass das Gebet von Schlechtem abhält.","Le Coran dit que la prière préserve des mauvaises actions.","El Corán dice que la oración aparta de lo malo."),
("Namaz günün içinde huzurlu bir moladır.","Das Gebet ist eine ruhige Pause mitten im Tag.","La prière est une pause paisible au milieu de la journée.","La oración es una pausa tranquila en medio del día.")]),
("Oruç",[
("Ramazan, kamerî takvimin dokuzuncu ayıdır.","Der Ramadan ist der neunte Monat des Mondkalenders.","Le Ramadan est le neuvième mois du calendrier lunaire.","Ramadán es el noveno mes del calendario lunar."),
("Kur'an bu ayda indirilmeye başlamıştır.","In diesem Monat begann die Offenbarung des Korans.","C'est pendant ce mois que la révélation du Coran a commencé.","En este mes comenzó la revelación del Corán."),
("Oruçlu kişi tan yerinden gün batımına kadar yemez ve içmez.","Der Fastende isst und trinkt von der Morgendämmerung bis zum Sonnenuntergang nicht.","Celui qui jeûne ne mange pas et ne boit pas de l'aube au coucher du soleil.","Quien ayuna no come ni bebe desde el alba hasta la puesta del sol."),
("Oruç yalnızca aç kalmak değildir.","Fasten heißt nicht nur, hungrig zu bleiben.","Le jeûne, ce n'est pas seulement avoir faim.","Ayunar no es solo pasar hambre."),
("Dil de yalandan ve gıybetten korunur.","Auch die Zunge wird vor Lüge und übler Nachrede bewahrt.","On préserve aussi sa langue du mensonge et de la médisance.","También se guarda la lengua de la mentira y la murmuración."),
("Hastalar ve yolcular orucu sonra kaza edebilir.","Kranke und Reisende können das Fasten später nachholen.","Les malades et les voyageurs peuvent rattraper le jeûne plus tard.","Los enfermos y los viajeros pueden recuperar el ayuno después."),
("Sahur yemeği bereketlidir.","Das Essen vor der Morgendämmerung ist gesegnet.","Le repas de l'aube est béni.","La comida del suhur es bendita."),
("Peygamberimiz orucu hurma veya suyla açardı.","Unser Prophet brach das Fasten mit Datteln oder Wasser.","Notre Prophète rompait le jeûne avec des dattes ou de l'eau.","Nuestro Profeta rompía el ayuno con dátiles o agua."),
("Ay sonunda fitre verilir ve bayram kutlanır.","Am Ende des Monats gibt man die Fitra und feiert das Fest.","À la fin du mois, on donne l'aumône de la rupture et on fête l'Aïd.","Al final del mes se da el zakat al-fitr y se celebra la fiesta."),
("Oruç, Allah'ın rızası için yapılan sabırlı bir ibadettir.","Das Fasten ist ein geduldiger Gottesdienst für das Wohlgefallen Allahs.","Le jeûne est un acte d'adoration patient accompli pour plaire à Allah.","El ayuno es una adoración paciente que se hace para complacer a Allah.")]),
("Zekât ve sadaka",[
("Zekât, malı belli bir miktara ulaşan Müslümanın borcudur.","Die Zakat ist eine Pflicht für Muslime, deren Vermögen eine bestimmte Grenze erreicht.","La zakat est un devoir pour le musulman dont les biens atteignent un certain seuil.","El azaque es una obligación para el musulmán cuyos bienes llegan a cierta cantidad."),
("Genellikle birikmiş malın kırkta biri verilir.","Meistens gibt man ein Vierzigstel des gesparten Vermögens.","En général, on donne un quarantième de l'épargne.","Normalmente se da la cuadragésima parte de los ahorros."),
("Zekât fakirlere, borçlulara ve yolda kalanlara verilir.","Die Zakat erhalten Arme, Verschuldete und Reisende in Not.","La zakat est donnée aux pauvres, aux endettés et aux voyageurs en difficulté.","El azaque se da a los pobres, a los endeudados y a los viajeros necesitados."),
("Zekât malı temizler ve bereketlendirir.","Die Zakat reinigt das Vermögen und segnet es.","La zakat purifie les biens et les bénit.","El azaque purifica los bienes y los bendice."),
("Sadaka ise her zaman verilebilir.","Die freiwillige Spende kann man jederzeit geben.","L'aumône volontaire peut être donnée à tout moment.","La limosna voluntaria se puede dar en cualquier momento."),
("Sadaka sadece para değildir.","Sadaqa ist nicht nur Geld.","La sadaqa, ce n'est pas seulement de l'argent.","La limosna no es solo dinero."),
("Güler yüz göstermek de sadakadır.","Ein freundliches Gesicht zu zeigen, ist auch Sadaqa.","Sourire à quelqu'un est aussi une aumône.","Sonreír a alguien también es limosna."),
("Yoldan bir taşı kaldırmak da sadakadır.","Einen Stein vom Weg zu entfernen, ist auch Sadaqa.","Enlever une pierre du chemin est aussi une aumône.","Quitar una piedra del camino también es limosna."),
("Sağ elin verdiğini sol el bilmemelidir.","Die linke Hand soll nicht wissen, was die rechte gibt.","La main gauche ne doit pas savoir ce que donne la main droite.","La mano izquierda no debe saber lo que da la derecha."),
("Verilen sadaka malı eksiltmez.","Eine Spende vermindert das Vermögen nicht.","L'aumône ne diminue pas les biens.","La limosna no disminuye los bienes.")]),
("Hac",[
("Hac, gücü yeten Müslümana ömründe bir kez farzdır.","Die Pilgerfahrt ist für jeden fähigen Muslim einmal im Leben Pflicht.","Le pèlerinage est obligatoire une fois dans la vie pour le musulman qui en a les moyens.","La peregrinación es obligatoria una vez en la vida para el musulmán que pueda hacerla."),
("Hac, Zilhicce ayında Mekke'de yapılır.","Die Pilgerfahrt findet im Monat Dhul-Hiddscha in Mekka statt.","Le pèlerinage a lieu à La Mecque pendant le mois de Dhou al-Hijja.","La peregrinación se hace en La Meca en el mes de Dhul Hiyya."),
("Hacılar ihram denen beyaz örtüler giyer.","Die Pilger tragen weiße Tücher, das sogenannte Ihram.","Les pèlerins portent des tissus blancs appelés ihram.","Los peregrinos visten unas telas blancas llamadas ihram."),
("Zengin ve fakir aynı kıyafetle yan yana durur.","Reiche und Arme stehen in derselben Kleidung nebeneinander.","Riches et pauvres se tiennent côte à côte dans les mêmes vêtements.","Ricos y pobres están uno al lado del otro con la misma ropa."),
("Hacılar Kâbe'nin etrafında yedi kez tavaf eder.","Die Pilger umrunden die Kaaba siebenmal.","Les pèlerins font sept fois le tour de la Kaaba.","Los peregrinos dan siete vueltas alrededor de la Kaaba."),
("Safa ile Merve tepeleri arasında yürürler.","Sie gehen zwischen den Hügeln Safa und Marwa hin und her.","Ils marchent entre les collines de Safa et Marwa.","Caminan entre las colinas de Safa y Marwa."),
("Bu, Hz. Hâcer'in su arayışını hatırlatır.","Das erinnert an Hadschars Suche nach Wasser.","Cela rappelle Hajar qui cherchait de l'eau.","Esto recuerda a Hayar buscando agua."),
("Haccın en önemli günü Arefe'dir.","Der wichtigste Tag der Pilgerfahrt ist der Tag von Arafat.","Le jour le plus important du pèlerinage est le jour d'Arafat.","El día más importante de la peregrinación es el día de Arafat."),
("Hacılar Arafat'ta dua ederek bekler.","Die Pilger stehen in Arafat und beten.","Les pèlerins se tiennent à Arafat en invoquant Allah.","Los peregrinos permanecen en Arafat haciendo súplicas."),
("Hac, bütün insanların Allah katında eşit olduğunu gösterir.","Die Pilgerfahrt zeigt, dass alle Menschen vor Allah gleich sind.","Le pèlerinage montre que tous les hommes sont égaux devant Allah.","La peregrinación muestra que todas las personas son iguales ante Allah.")]),
("Kur'an-ı Kerim",[
("Kur'an, Allah'ın son kitabıdır.","Der Koran ist das letzte Buch Allahs.","Le Coran est le dernier livre d'Allah.","El Corán es el último libro de Allah."),
("Cebrail aracılığıyla Hz. Muhammed'e indirilmiştir.","Er wurde durch den Engel Gabriel dem Propheten Muhammad offenbart.","Il a été révélé au Prophète Muhammad par l'ange Gabriel.","Fue revelado al Profeta Muhammad por medio del ángel Gabriel."),
("Vahiy yaklaşık yirmi üç yıl sürmüştür.","Die Offenbarung dauerte etwa dreiundzwanzig Jahre.","La révélation a duré environ vingt-trois ans.","La revelación duró unos veintitrés años."),
("İlk inen âyetler \"Oku!\" emriyle başlar.","Die ersten offenbarten Verse beginnen mit dem Befehl „Lies!“.","Les premiers versets révélés commencent par l'ordre « Lis ! ».","Los primeros versículos revelados empiezan con la orden «¡Lee!»."),
("Kur'an yüz on dört sûreden oluşur.","Der Koran besteht aus einhundertvierzehn Suren.","Le Coran se compose de cent quatorze sourates.","El Corán tiene ciento catorce suras."),
("En uzun sûre Bakara, en kısası Kevser'dir.","Die längste Sure ist al-Baqara, die kürzeste al-Kauthar.","La plus longue sourate est al-Baqara, la plus courte est al-Kawthar.","La sura más larga es al-Baqara y la más corta, al-Kawthar."),
("Kur'an otuz cüze ayrılmıştır.","Der Koran ist in dreißig Teile eingeteilt.","Le Coran est divisé en trente parties.","El Corán está dividido en treinta partes."),
("Milyonlarca Müslüman onu ezberlemiştir.","Millionen von Muslimen haben ihn auswendig gelernt.","Des millions de musulmans l'ont appris par cœur.","Millones de musulmanes lo han memorizado."),
("Peygamberimiz \"Sizin en hayırlınız Kur'an'ı öğrenen ve öğretendir\" buyurmuştur.","Unser Prophet sagte: „Die Besten unter euch sind die, die den Koran lernen und lehren.“","Notre Prophète a dit : « Les meilleurs d'entre vous sont ceux qui apprennent le Coran et l'enseignent. »","Nuestro Profeta dijo: «Los mejores de vosotros son quienes aprenden el Corán y lo enseñan»."),
("Kur'an okumak kalbe huzur verir.","Den Koran zu lesen, gibt dem Herzen Ruhe.","Lire le Coran apaise le cœur.","Leer el Corán da paz al corazón.")]),
("Peygamberimiz",[
("Hz. Muhammed 571 yılında Mekke'de doğdu.","Muhammad wurde im Jahr 571 in Mekka geboren.","Muhammad est né à La Mecque en 571.","Muhammad nació en La Meca en el año 571."),
("Babası o doğmadan önce vefat etmişti.","Sein Vater starb vor seiner Geburt.","Son père est mort avant sa naissance.","Su padre murió antes de que naciera."),
("Annesi de o altı yaşındayken vefat etti.","Seine Mutter starb, als er sechs Jahre alt war.","Sa mère est morte quand il avait six ans.","Su madre murió cuando él tenía seis años."),
("Gençliğinde dürüstlüğüyle tanındı.","In seiner Jugend war er für seine Ehrlichkeit bekannt.","Dans sa jeunesse, il était connu pour son honnêteté.","En su juventud era conocido por su honradez."),
("İnsanlar ona \"el-Emîn\", yani güvenilir derdi.","Die Menschen nannten ihn „al-Amin“, den Vertrauenswürdigen.","Les gens l'appelaient « al-Amin », le digne de confiance.","La gente lo llamaba «al-Amín», el digno de confianza."),
("Kırk yaşında ilk vahiy geldi.","Mit vierzig Jahren kam die erste Offenbarung.","À quarante ans, il a reçu la première révélation.","A los cuarenta años recibió la primera revelación."),
("622 yılında Medine'ye hicret etti.","Im Jahr 622 wanderte er nach Medina aus.","En 622, il a émigré à Médine.","En el año 622 emigró a Medina."),
("Çocuklara, yaşlılara ve hayvanlara karşı çok merhametliydi.","Er war sehr barmherzig zu Kindern, Alten und Tieren.","Il était très miséricordieux envers les enfants, les personnes âgées et les animaux.","Era muy compasivo con los niños, los ancianos y los animales."),
("Evde ailesine yardım eder, kendi elbisesini dikerdi.","Zu Hause half er seiner Familie und nähte seine Kleidung selbst.","À la maison, il aidait sa famille et raccommodait lui-même ses vêtements.","En casa ayudaba a su familia y se cosía su propia ropa."),
("Kur'an onu \"âlemlere rahmet\" olarak tanıtır.","Der Koran beschreibt ihn als „Barmherzigkeit für die Welten“.","Le Coran le présente comme « une miséricorde pour les mondes ».","El Corán lo presenta como «misericordia para los mundos».")]),
("Güzel ahlak",[
("Peygamberimiz \"Ben güzel ahlakı tamamlamak için gönderildim\" buyurmuştur.","Unser Prophet sagte: „Ich wurde gesandt, um den guten Charakter zu vollenden.“","Notre Prophète a dit : « J'ai été envoyé pour parfaire le bon caractère. »","Nuestro Profeta dijo: «He sido enviado para perfeccionar el buen carácter»."),
("Müslüman dürüst konuşur ve sözünü tutar.","Ein Muslim spricht die Wahrheit und hält sein Wort.","Le musulman dit la vérité et tient parole.","El musulmán dice la verdad y cumple su palabra."),
("Emanete hıyanet etmez.","Er missbraucht kein anvertrautes Gut.","Il ne trahit pas ce qu'on lui confie.","No traiciona lo que se le confía."),
("Anne babasına iyilik eder ve onlara \"öf\" bile demez.","Er ist gut zu seinen Eltern und sagt nicht einmal „uff“ zu ihnen.","Il est bon envers ses parents et ne leur dit même pas « ouf ».","Es bueno con sus padres y no les dice ni siquiera «uf»."),
("Komşusu aç iken tok yatmaz.","Er schläft nicht satt, während sein Nachbar hungrig ist.","Il ne se couche pas rassasié quand son voisin a faim.","No se acuesta saciado mientras su vecino pasa hambre."),
("Öfkesini yener ve affeder.","Er beherrscht seinen Zorn und vergibt.","Il maîtrise sa colère et pardonne.","Controla su ira y perdona."),
("Kimsenin arkasından kötü konuşmaz.","Er redet hinter niemandes Rücken schlecht.","Il ne dit du mal de personne en son absence.","No habla mal de nadie a sus espaldas."),
("Kendisi için istediğini kardeşi için de ister.","Er wünscht seinem Bruder, was er sich selbst wünscht.","Il souhaite pour son frère ce qu'il souhaite pour lui-même.","Desea para su hermano lo que desea para sí mismo."),
("İşini en güzel şekilde yapar.","Er macht seine Arbeit so gut wie möglich.","Il fait son travail de la meilleure façon.","Hace su trabajo de la mejor manera."),
("Güzel ahlak, kıyamet günü mizanda en ağır gelecek şeydir.","Guter Charakter wird am Jüngsten Tag auf der Waage am schwersten wiegen.","Le bon caractère sera ce qu'il y a de plus lourd dans la balance le Jour dernier.","El buen carácter será lo que más pese en la balanza el Día del Juicio.")])]
